#include "mock_logger.h"
#include <string.h>

// 100-byte compressed RAM buffer captured from Member 1's Wokwi test.
// For this integration stage, the UART protocol treats these bytes as
// opaque compressed data and only verifies that they arrive unchanged.
static const uint8_t initial_logger_data[] = {
    0x80, 0x96, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x81,
    0xF4, 0x40, 0x00, 0x80, 0xBF, 0xE8, 0x09, 0xEC,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00
};

const uint8_t *mock_logger_data(void)
{
    return initial_logger_data;
}

size_t mock_logger_length(void)
{
    return sizeof(initial_logger_data);
}

bool mock_logger_matches(const uint8_t *data, size_t length)
{
    return length == sizeof(initial_logger_data) &&
           memcmp(data, initial_logger_data, length) == 0;
}